import { useEffect, useState, type FormEvent } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { Activity, ArrowLeft, BarChart3, Bot, CheckCircle2, CircleAlert, Cpu, FlaskConical, KeyRound, Plus, Power, RefreshCw, Save, Send, Trash2 } from 'lucide-react';
import { Link, useParams } from 'react-router-dom';
import { Badge, Button, Card, EmptyState, ErrorState, Field, LoadingState, PageHeader } from '../../components/ui';
import { api, formatApiError, jsonBody } from '../../lib/api';

type Company = { id: string; name: string; code: string; description: string | null; contact_email: string | null; contact_phone: string | null; time_zone: string; is_enabled: boolean; flow_key: string | null; notification_mode: 'disabled' | 'always' | 'outside_business_hours'; notification_recipients: string[]; business_hours_start: string | null; business_hours_end: string | null; agent_farewell_message: string | null; user_count: number; open_conversations: number; contact_count: number };
export function CompanyPage() {
  const { companyId = '', section = 'overview' } = useParams();
  const query = useQuery({ queryKey: ['company', companyId], queryFn: () => api<Company>(`/admin/companies/${companyId}`), enabled: Boolean(companyId) });
  useEffect(() => {
    const targets: Record<string, string> = { integracion: 'section-whatsapp', usuarios: 'section-users', plantillas: 'section-templates', ia: 'section-ai', 'analitica-ia': 'section-ai-analytics', auditoria: 'section-audit' };
    const target = targets[section];
    if (query.data && target) requestAnimationFrame(() => document.getElementById(target)?.scrollIntoView({ block: 'start' }));
  }, [query.data, section]);
  if (query.isLoading) return <LoadingState label="Cargando empresa…" />;
  if (query.isError || !query.data) return <ErrorState message={formatApiError(query.error)} />;
  const company = query.data;
  return <><Link className="back-link" to="/administracion/empresas"><ArrowLeft size={15} />Volver</Link><PageHeader eyebrow={company.code} title={`Editar empresa: ${company.name}`} description="Configuración global de empresa, WhatsApp Cloud API, usuarios y plantillas." action={<Badge tone={company.is_enabled ? 'green' : 'neutral'}>{company.is_enabled ? 'Activa' : 'Deshabilitada'}</Badge>} />
    <nav className="company-section-nav" aria-label="Secciones de empresa"><a href="#section-company">Información general</a><a href="#section-workspaces">Empresa digital</a><a href="#section-whatsapp">WhatsApp Cloud API</a><a href="#section-ai">IA</a><a href="#section-users">Admin principal</a><a href="#section-users">Usuarios</a><a href="#section-templates">Plantillas</a><a href="#section-health">Módulos y salud</a><a href="#section-events">Eventos</a><a href="#section-audit">Auditoría</a></nav>
    <section id="section-workspaces"><Card className="panel-card company-workspaces"><div className="card-heading"><div><p className="eyebrow">Empresa digital</p><h2>Configuraciones propias de esta empresa</h2><p>Todo lo que abras aquí se carga y se guarda solo para esta empresa.</p></div></div><div className="workspace-card-grid"><article><h3>Chatbot web</h3><p>Constructor, widget y contenido del chatbot web de esta empresa.</p><div><Link to={`/administracion/empresas/${companyId}/automatizacion/webchat/flujos`}>Constructor</Link><Link to={`/administracion/empresas/${companyId}/automatizacion/webchat/widget`}>Widget</Link><Link to={`/administracion/empresas/${companyId}/automatizacion/webchat/accesos`}>Accesos rápidos</Link><Link to={`/administracion/empresas/${companyId}/automatizacion/webchat/preguntas`}>Preguntas frecuentes</Link><Link to={`/administracion/empresas/${companyId}/automatizacion/webchat/articulos`}>Artículos</Link><Link to={`/administracion/empresas/${companyId}/automatizacion/webchat/instalaciones`}>Instalaciones</Link></div></article><article><h3>Bot de WhatsApp</h3><p>Constructor visual del flujo conversacional de WhatsApp para esta empresa.</p><div><Link to={`/administracion/empresas/${companyId}/automatizacion/whatsapp`}>Constructor</Link></div></article><article><h3>Conversaciones</h3><p>Acceso al flujo operativo y a los chats de esta empresa.</p><div><Link to={`/administracion/empresas/${companyId}/conversaciones`}>Abrir chats</Link></div></article><article><h3>Analíticas</h3><p>Reportes generales y por agente de esta empresa.</p><div><Link to={`/administracion/empresas/${companyId}/reportes`}>Generales</Link><Link to={`/administracion/empresas/${companyId}/reportes/agentes`}>Por agente</Link><Link to={`/administracion/empresas/${companyId}/analitica-ia`}>Análisis IA</Link></div></article></div></Card></section>
    <section id="section-company"><GeneralSettings company={company} /></section>
    <section id="section-whatsapp"><IntegrationPanel companyId={companyId} /></section>
    <section id="section-ai"><AiPanel companyId={companyId} /></section>
    <section id="section-ai-analytics"><AiAnalyticsPanel companyId={companyId} /></section>
    <section id="section-users"><UsersPanel companyId={companyId} /></section>
    <section id="section-templates"><TemplatesPanel companyId={companyId} /></section>
    <section id="section-health"><CompanyOverviewPanel companyId={companyId} /></section>
    <section id="section-audit"><AuditPanel companyId={companyId} /></section>
  </>;
}

function GeneralSettings({ company }: { company: Company }) {
  const client = useQueryClient();
  const mutation = useMutation({ mutationFn: (body: unknown) => api(`/admin/companies/${company.id}`, { method: 'PUT', ...jsonBody(body) }), onSuccess: () => client.invalidateQueries({ queryKey: ['company', company.id] }) });
  function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const form = new FormData(event.currentTarget); mutation.mutate({ name: form.get('name'), code: form.get('code'), description: form.get('description') || null, contactEmail: form.get('email') || null, contactPhone: form.get('phone') || null, timeZone: form.get('timezone'), isEnabled: form.get('enabled') === 'on', flowKey: form.get('flowKey') || null, notificationMode: form.get('notificationMode'), notificationRecipients: String(form.get('notificationRecipients') ?? '').split(',').map((item) => item.trim()).filter(Boolean), businessHoursStart: form.get('start') || null, businessHoursEnd: form.get('end') || null, agentFarewellMessage: form.get('farewell') || null }); }
  return <Card className="form-card"><form onSubmit={submit}><div className="form-section"><div><h2>Información general</h2><p>Datos visibles y parámetros operativos de la empresa.</p></div><div className="form-grid"><Field label="Nombre"><input name="name" defaultValue={company.name} required /></Field><Field label="Código"><input name="code" defaultValue={company.code} required /></Field><Field label="Descripción"><textarea name="description" rows={2} defaultValue={company.description ?? ''} /></Field><Field label="Correo de contacto"><input name="email" type="email" defaultValue={company.contact_email ?? ''} /></Field><Field label="Teléfono"><input name="phone" defaultValue={company.contact_phone ?? ''} /></Field><Field label="Zona horaria"><input name="timezone" defaultValue={company.time_zone} readOnly required /></Field><Field label="Flow key"><input name="flowKey" defaultValue={company.flow_key ?? ''} /></Field><Field label="Modo de notificaciones"><select name="notificationMode" defaultValue={company.notification_mode}><option value="disabled">Deshabilitadas</option><option value="always">Siempre</option><option value="outside_business_hours">Fuera del horario</option></select></Field><Field label="Destinatarios de notificaciones" hint="Correos separados por coma"><input name="notificationRecipients" defaultValue={(company.notification_recipients ?? []).join(', ')} placeholder="correo1@dominio.com, correo2@dominio.com" /></Field><label className="toggle-field"><input name="enabled" type="checkbox" defaultChecked={company.is_enabled} /><span />Empresa habilitada</label></div></div><div className="form-section"><div><h2>Horario y cierre</h2><p>La IA usa este horario sin convertirlo manualmente.</p></div><div className="form-grid"><Field label="Apertura"><input name="start" type="time" defaultValue={company.business_hours_start?.slice(0, 5) ?? ''} /></Field><Field label="Cierre"><input name="end" type="time" defaultValue={company.business_hours_end?.slice(0, 5) ?? ''} /></Field><Field label="Despedida del agente"><textarea name="farewell" rows={4} maxLength={1000} defaultValue={company.agent_farewell_message ?? ''} /></Field></div></div><div className="form-actions">{mutation.isError && <span className="form-error">{formatApiError(mutation.error)}</span>}{mutation.isSuccess && <span className="success-text"><CheckCircle2 size={16} />Guardado</span>}<Link className="button button--secondary" to="/administracion/empresas">Cancelar</Link><Button type="submit" disabled={mutation.isPending}><Save size={16} />{mutation.isPending ? 'Guardando…' : 'Guardar empresa'}</Button></div></form></Card>;
}

function IntegrationPanel({ companyId }: { companyId: string }) {
  const client = useQueryClient();
  const query = useQuery({ queryKey: ['integration', companyId], queryFn: () => api<Record<string, unknown> | null>(`/admin/companies/${companyId}/integration`) });
  const mutation = useMutation({ mutationFn: (body: unknown) => api(`/admin/companies/${companyId}/integration`, { method: 'PUT', ...jsonBody(body) }), onSuccess: () => client.invalidateQueries({ queryKey: ['integration', companyId] }) });
  const test = useMutation({ mutationFn: () => api<{ success: boolean; phoneNumber: string | null; verifiedName: string | null }>(`/admin/companies/${companyId}/integration/test`, { method: 'POST', ...jsonBody({}) }) });
  if (query.isLoading) return <LoadingState />;
  const integration = query.data;
  function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const form = new FormData(event.currentTarget); mutation.mutate({ phoneNumberId: form.get('phoneNumberId'), wabaId: form.get('wabaId') || null, appId: form.get('appId') || null, accessToken: form.get('accessToken') || undefined, appSecret: form.get('appSecret') || undefined, verifyToken: form.get('verifyToken') || undefined, apiBaseUrl: form.get('apiBaseUrl'), apiVersion: form.get('apiVersion'), isActive: form.get('active') === 'on' }); }
  return <Card className="form-card"><form onSubmit={submit}><div className="form-section"><div><span className="section-icon"><KeyRound size={19} /></span><h2>WhatsApp Cloud API</h2><p>Los secretos se cifran con AES-GCM y nunca vuelven al navegador.</p></div><div className="form-grid"><Field label="Proveedor"><input value={String(integration?.provider ?? 'whatsapp_cloud')} readOnly /></Field><Field label="Phone Number ID"><input name="phoneNumberId" defaultValue={String(integration?.phone_number_id ?? '')} required /></Field><Field label="WABA ID"><input name="wabaId" defaultValue={String(integration?.waba_id ?? '')} /></Field><Field label="App ID"><input name="appId" defaultValue={String(integration?.app_id ?? '')} /></Field><Field label="API Base URL"><input name="apiBaseUrl" type="url" defaultValue={String(integration?.api_base_url ?? 'https://graph.facebook.com')} required /></Field><Field label="Versión de Graph"><input name="apiVersion" defaultValue={String(integration?.api_version ?? 'v23.0')} required /></Field><Field label="Access token" hint={integration?.has_access_token ? 'Configurado. Déjalo vacío para conservarlo.' : 'Obligatorio antes de activar.'}><input name="accessToken" type="password" autoComplete="new-password" /></Field><Field label="App secret" hint={integration?.has_app_secret ? 'Configurado. Déjalo vacío para conservarlo.' : 'Se usa para validar la firma del webhook.'}><input name="appSecret" type="password" autoComplete="new-password" /></Field><Field label="Verify token" hint={integration?.has_verify_token ? 'Configurado. Déjalo vacío para conservarlo.' : 'Se guarda solo su hash.'}><input name="verifyToken" type="password" autoComplete="new-password" /></Field><label className="toggle-field"><input name="active" type="checkbox" defaultChecked={Boolean(integration?.is_active)} /><span />Integración activa</label></div></div><div className="security-note"><KeyRound size={18} /><p>Webhook: <code>/v1/meta/webhook/{String(integration?.phone_number_id ?? '{phone-number-id}')}</code></p></div><div className="form-actions">{(mutation.isError || test.isError) && <span className="form-error">{formatApiError(mutation.error ?? test.error)}</span>}{test.isSuccess && <span className="success-text"><CheckCircle2 size={16} />{test.data.verifiedName ?? test.data.phoneNumber ?? 'Conexión válida'}</span>}<Button type="button" variant="secondary" onClick={() => test.mutate()} disabled={!integration?.is_active || test.isPending}><FlaskConical size={16} />{test.isPending ? 'Probando…' : 'Probar conexión con Meta'}</Button><Button type="submit" disabled={mutation.isPending}><Save size={16} />Guardar integración</Button></div></form></Card>;
}

type CompanyUser = { id: string; auth_user_id: string | null; name: string; email: string; phone: string | null; role: 'admin' | 'agent'; status: boolean; password_migration_status: string };

function UsersPanel({ companyId }: { companyId: string }) {
  const client = useQueryClient();
  const [editing, setEditing] = useState<CompanyUser | 'new' | null>(null);
  const [resetting, setResetting] = useState<CompanyUser | null>(null);
  const query = useQuery({ queryKey: ['company-users', companyId], queryFn: () => api<CompanyUser[]>(`/admin/companies/${companyId}/users`) });
  const save = useMutation({ mutationFn: ({ target, body }: { target: CompanyUser | 'new'; body: unknown }) => api(`/admin/companies/${companyId}/users${target === 'new' ? '' : `/${target.id}`}`, { method: target === 'new' ? 'POST' : 'PUT', ...jsonBody(body) }), onSuccess: async () => { setEditing(null); await client.invalidateQueries({ queryKey: ['company-users', companyId] }); } });
  const toggle = useMutation({ mutationFn: (id: string) => api(`/admin/companies/${companyId}/users/${id}/toggle`, { method: 'PATCH', ...jsonBody({}) }), onSuccess: () => client.invalidateQueries({ queryKey: ['company-users', companyId] }) });
  const reset = useMutation({ mutationFn: ({ id, password }: { id: string; password: string }) => api(`/admin/companies/${companyId}/users/${id}/password`, { method: 'POST', ...jsonBody({ password }) }), onSuccess: async () => { setResetting(null); await client.invalidateQueries({ queryKey: ['company-users', companyId] }); } });
  const primaryAdmin = query.data?.find((user) => user.role === 'admin') ?? null;
  const agentEmailLocked = editing !== null && editing !== 'new' && editing.role === 'agent';
  function submitUser(event: FormEvent<HTMLFormElement>, target: CompanyUser | 'new') { event.preventDefault(); const form = new FormData(event.currentTarget); save.mutate({ target, body: { name: form.get('name'), email: form.get('email'), phone: form.get('phone') || null, role: form.get('role'), password: form.get('password') || undefined, status: form.get('status') === 'on' } }); }
  return <>
    <Card className="form-card primary-admin-card"><form onSubmit={(event) => submitUser(event, primaryAdmin ?? 'new')}><div className="form-section"><div><h2>Administrador principal</h2></div><div className="form-grid"><Field label="Nombre"><input name="name" required defaultValue={primaryAdmin?.name ?? ''} /></Field><Field label="Correo"><input name="email" type="email" required defaultValue={primaryAdmin?.email ?? ''} /></Field><Field label="Teléfono"><input name="phone" defaultValue={primaryAdmin?.phone ?? ''} /></Field><Field label="Contraseña" hint={primaryAdmin ? 'Déjala vacía para conservarla.' : 'Mínimo 8 caracteres.'}><input name="password" type="password" minLength={8} required={!primaryAdmin} autoComplete="new-password" /></Field><input name="role" type="hidden" value="admin" /><label className="toggle-field"><input name="status" type="checkbox" defaultChecked={primaryAdmin?.status ?? true} /><span />Usuario habilitado</label></div></div><div className="form-actions"><Button type="submit" disabled={save.isPending}>Guardar admin principal</Button></div></form></Card>
    <div className="section-toolbar"><div><h2>Usuarios</h2></div><Button onClick={() => setEditing('new')}><Plus size={16} />Nuevo usuario</Button></div>
    {editing && <Card className="form-card"><form onSubmit={(event) => submitUser(event, editing)}><div className="form-section"><div><h2>{editing === 'new' ? 'Nuevo usuario' : 'Editar usuario'}</h2></div><div className="form-grid"><Field label="Nombre"><input name="name" required defaultValue={editing === 'new' ? '' : editing.name} /></Field><Field label="Correo" hint={agentEmailLocked ? 'El correo de las cuentas de agente no se puede editar.' : 'Se actualizará también el correo de inicio de sesión.'}><input name="email" type="email" required readOnly={agentEmailLocked} defaultValue={editing === 'new' ? '' : editing.email} /></Field><Field label="Teléfono"><input name="phone" defaultValue={editing === 'new' ? '' : editing.phone ?? ''} /></Field><Field label="Rol"><select name="role" defaultValue={editing === 'new' ? 'agent' : editing.role}><option value="agent">Agente</option><option value="admin">Administrador</option></select></Field><Field label="Contraseña" hint={editing === 'new' ? 'Mínimo 8 caracteres.' : 'Déjala vacía para conservarla.'}><input name="password" type="password" minLength={8} required={editing === 'new'} autoComplete="new-password" /></Field><label className="toggle-field"><input name="status" type="checkbox" defaultChecked={editing === 'new' || editing.status} /><span />Usuario habilitado</label></div></div><div className="form-actions"><Button type="button" variant="secondary" onClick={() => setEditing(null)}>Limpiar</Button><Button type="submit" disabled={save.isPending}>Guardar usuario</Button></div></form></Card>}
    {resetting && <Card className="inline-form"><form onSubmit={(event) => { event.preventDefault(); reset.mutate({ id: resetting.id, password: String(new FormData(event.currentTarget).get('password') ?? '') }); }}><div><strong>Resetear contraseña de {resetting.name}</strong></div><input name="password" type="password" minLength={8} required placeholder="Nueva contraseña" autoComplete="new-password" /><Button type="submit" disabled={reset.isPending}>Resetear contraseña</Button><Button type="button" variant="ghost" onClick={() => setResetting(null)}>Cancelar</Button></form></Card>}
    {(save.isError || toggle.isError || reset.isError) && <p className="form-error standalone-message">{formatApiError(save.error ?? toggle.error ?? reset.error)}</p>}
    {reset.isSuccess && <p className="success-text standalone-message"><CheckCircle2 size={16} />Contraseña actualizada.</p>}
    {query.isLoading ? <LoadingState /> : query.data?.length ? <Card className="table-card"><div className="data-table-wrap"><table className="data-table"><thead><tr><th>Usuario</th><th>Rol</th><th>Estado</th><th>Acceso</th><th>Acciones</th></tr></thead><tbody>{query.data.map((user) => <tr key={user.id}><td><div className="table-person"><span className="avatar avatar--small">{user.name.slice(0, 2).toUpperCase()}</span><div><strong>{user.name}</strong><span>{user.email}</span></div></div></td><td>{user.role === 'admin' ? 'Administrador' : 'Agente'}</td><td><Badge tone={user.status ? 'green' : 'neutral'}>{user.status ? 'Activo' : 'Deshabilitado'}</Badge></td><td>{user.password_migration_status}</td><td><div className="table-actions"><Button variant="ghost" onClick={() => setEditing(user)}>Editar</Button><Button variant="ghost" onClick={() => setResetting(user)}>Contraseña</Button><Button variant="ghost" onClick={() => toggle.mutate(user.id)}><Power size={14} />{user.status ? 'Deshabilitar' : 'Habilitar'}</Button></div></td></tr>)}</tbody></table></div></Card> : <EmptyState title="Sin usuarios" detail="Crea el primer administrador o agente." />}
  </>;
}

function TemplatesPanel({ companyId }: { companyId: string }) {
  const client = useQueryClient();
  const [editing, setEditing] = useState<Record<string, unknown> | 'new' | null>(null);
  const [testing, setTesting] = useState<Record<string, unknown> | null>(null);
  const query = useQuery({ queryKey: ['templates', companyId], queryFn: () => api<Array<Record<string, unknown>>>(`/admin/companies/${companyId}/templates`) });
  const sync = useMutation({ mutationFn: () => api<{ synced: number }>(`/admin/companies/${companyId}/templates/sync`, { method: 'POST', ...jsonBody({}) }), onSuccess: () => client.invalidateQueries({ queryKey: ['templates', companyId] }) });
  const save = useMutation({ mutationFn: (body: unknown) => api(`/admin/companies/${companyId}/templates${editing === 'new' ? '' : `/${String(editing?.id)}`}`, { method: editing === 'new' ? 'POST' : 'PUT', ...jsonBody(body) }), onSuccess: async () => { setEditing(null); await client.invalidateQueries({ queryKey: ['templates', companyId] }); } });
  const remove = useMutation({ mutationFn: (id: string) => api(`/admin/companies/${companyId}/templates/${id}`, { method: 'DELETE' }), onSuccess: () => client.invalidateQueries({ queryKey: ['templates', companyId] }) });
  const test = useMutation({ mutationFn: (body: unknown) => api(`/admin/companies/${companyId}/templates/test-send`, { method: 'POST', ...jsonBody(body) }), onSuccess: () => setTesting(null) });
  const current = editing === 'new' ? null : editing;
  return <><div className="section-toolbar"><div><h2>Plantillas de WhatsApp</h2></div><div className="button-row"><Button variant="secondary" onClick={() => setEditing('new')}><Plus size={16} />Nueva plantilla</Button><Button onClick={() => sync.mutate()} disabled={sync.isPending}><RefreshCw size={16} />{sync.isPending ? 'Sincronizando…' : 'Sincronizar desde Meta'}</Button></div></div>
    {editing && <Card className="form-card"><form onSubmit={(event) => { event.preventDefault(); const form = new FormData(event.currentTarget); save.mutate({ name: form.get('name'), language: form.get('language'), templateIdentifier: form.get('identifier') || null, bodyParamCount: Number(form.get('params')), isActive: form.get('active') === 'on', metaComponents: current?.meta_components ?? [] }); }}><div className="form-section"><div><h2>{current ? 'Editar plantilla' : 'Nueva plantilla'}</h2></div><div className="form-grid"><Field label="Nombre"><input name="name" required defaultValue={String(current?.name ?? '')} /></Field><Field label="Idioma"><input name="language" required defaultValue={String(current?.language ?? 'es')} /></Field><Field label="Identificador de plantilla"><input name="identifier" defaultValue={String(current?.template_identifier ?? '')} /></Field><Field label="Cantidad de parámetros del cuerpo"><input name="params" required type="number" min="0" defaultValue={Number(current?.body_param_count ?? 0)} /></Field><label className="toggle-field"><input name="active" type="checkbox" defaultChecked={current ? Boolean(current.is_active) : true} /><span />Plantilla activa</label></div></div><div className="form-actions"><Button type="button" variant="secondary" onClick={() => setEditing(null)}>Limpiar</Button><Button type="submit" disabled={save.isPending}>Guardar plantilla</Button></div></form></Card>}
    {testing && <Card className="form-card"><form onSubmit={(event) => { event.preventDefault(); const form = new FormData(event.currentTarget); const split = (name: string) => String(form.get(name) ?? '').split('|').map((item) => item.trim()).filter(Boolean); test.mutate({ templateId: String(testing.id), recipient: form.get('recipient'), headerParameters: split('headerParameters'), headerMediaUrl: form.get('headerMediaUrl') || null, parameters: split('parameters') }); }}><div className="form-section"><div><h2>Enviar prueba: {String(testing.name)}</h2></div><div className="form-grid"><Field label="Plantilla"><input value={`${String(testing.name)} (${String(testing.language)})`} readOnly /></Field><Field label="Variables de cabecera" hint="Separadas por |"><input name="headerParameters" placeholder="Título|1234" /></Field><Field label="URL de medio de cabecera"><input name="headerMediaUrl" type="url" placeholder="https://..." /></Field><Field label="Teléfono destino"><input name="recipient" required placeholder="506..." /></Field><Field label="Variables del cuerpo" hint="Separadas por |"><input name="parameters" placeholder="Juan|Pedido 123" /></Field></div></div><div className="form-actions"><Button type="button" variant="secondary" onClick={() => setTesting(null)}>Cancelar</Button><Button type="submit" disabled={test.isPending}><Send size={15} />Enviar prueba</Button></div></form></Card>}
    {(sync.isError || save.isError || remove.isError || test.isError) && <p className="form-error standalone-message">{formatApiError(sync.error ?? save.error ?? remove.error ?? test.error)}</p>}{sync.isSuccess && <p className="success-text standalone-message"><CheckCircle2 size={16} />{sync.data.synced} plantillas sincronizadas.</p>}{test.isSuccess && <p className="success-text standalone-message"><CheckCircle2 size={16} />Mensaje de prueba encolado.</p>}
    {query.isLoading ? <LoadingState /> : query.data?.length ? <div className="template-grid">{query.data.map((template) => <Card key={String(template.id)} className="template-card"><div><Badge tone={template.meta_status === 'APPROVED' ? 'green' : 'neutral'}>{String(template.meta_status ?? 'Local')}</Badge><small>{String(template.language)}</small></div><h3>{String(template.name)}</h3><p>{Number(template.body_param_count)} variables · {String(template.template_identifier ?? 'Sin identificador')}</p><div className="card-actions"><Button variant="ghost" onClick={() => setEditing(template)}>Editar</Button><Button variant="ghost" onClick={() => setTesting(template)}><Send size={14} />Probar</Button><Button variant="ghost" aria-label={`Eliminar ${String(template.name)}`} onClick={() => { if (window.confirm('¿Eliminar esta plantilla?')) remove.mutate(String(template.id)); }}><Trash2 size={14} />Eliminar</Button></div></Card>)}</div> : <EmptyState title="Sin plantillas" detail="Sincroniza con Meta o crea una plantilla para comenzar." />}</>;
}

function AiPanelLegacy({ companyId }: { companyId: string }) {
  const client = useQueryClient();
  const [addingKnowledge, setAddingKnowledge] = useState(false);
  const query = useQuery({ queryKey: ['ai', companyId], queryFn: () => api<{ settings: Record<string, unknown> | null; knowledge: Array<Record<string, unknown>> }>(`/admin/companies/${companyId}/ai`) });
  const mutation = useMutation({ mutationFn: (body: unknown) => api(`/admin/companies/${companyId}/ai`, { method: 'PUT', ...jsonBody(body) }), onSuccess: () => client.invalidateQueries({ queryKey: ['ai', companyId] }) });
  const test = useMutation({ mutationFn: () => api<{ response: string; durationMs: number }>(`/admin/companies/${companyId}/ai/test`, { method: 'POST', ...jsonBody({ prompt: 'Responde únicamente: conexión correcta' }) }), onSuccess: () => client.invalidateQueries({ queryKey: ['ai', companyId] }) });
  const addKnowledge = useMutation({ mutationFn: (body: unknown) => api(`/admin/companies/${companyId}/ai/knowledge`, { method: 'POST', ...jsonBody(body) }), onSuccess: async () => { setAddingKnowledge(false); await client.invalidateQueries({ queryKey: ['ai', companyId] }); } });
  const deleteKnowledge = useMutation({ mutationFn: (id: string) => api(`/admin/companies/${companyId}/ai/knowledge/${id}`, { method: 'DELETE' }), onSuccess: () => client.invalidateQueries({ queryKey: ['ai', companyId] }) });
  if (query.isLoading) return <LoadingState />; const settings = query.data?.settings;
  function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const form = new FormData(event.currentTarget); mutation.mutate({ isEnabled: form.get('enabled') === 'on', provider: form.get('provider'), model: form.get('model'), apiKey: form.get('apiKey') || undefined, apiBaseUrl: form.get('apiBaseUrl') || null, responseMode: form.get('responseMode'), systemPrompt: form.get('systemPrompt') || null, fallbackMessage: form.get('fallback') || null, temperature: Number(form.get('temperature')), maxTokens: Number(form.get('maxTokens')), dailyMessageLimit: form.get('daily') ? Number(form.get('daily')) : null, monthlyMessageLimit: form.get('monthly') ? Number(form.get('monthly')) : null, pauseWhenAssigned: true, escalateOnHumanRequest: true }); }
  return <div className="settings-columns"><Card className="form-card"><form onSubmit={submit}><div className="form-section"><div><span className="section-icon"><Bot size={19} /></span><h2>Asistente IA</h2><p>Se detiene cuando un agente toma la conversación y escala solicitudes humanas.</p></div><div className="form-grid"><label className="toggle-field"><input name="enabled" type="checkbox" defaultChecked={Boolean(settings?.is_enabled)} /><span />IA habilitada</label><Field label="Proveedor"><select name="provider" defaultValue={String(settings?.provider ?? 'openai')}><option value="openai">OpenAI</option><option value="deepseek">DeepSeek</option><option value="gemini">Gemini</option></select></Field><Field label="Modelo"><input name="model" defaultValue={String(settings?.model ?? 'gpt-4.1-mini')} required /></Field><Field label="API key" hint={settings?.has_api_key ? 'Configurada. Déjala vacía para conservarla.' : ''}><input name="apiKey" type="password" autoComplete="new-password" /></Field><Field label="URL base opcional"><input name="apiBaseUrl" defaultValue={String(settings?.api_base_url ?? '')} /></Field><Field label="Cuándo responder"><select name="responseMode" defaultValue={String(settings?.response_mode ?? 'outside_business_hours')}><option value="outside_business_hours">Fuera del horario</option><option value="always">Siempre</option><option value="unassigned">Solo sin agente</option><option value="disabled">Nunca</option></select></Field><Field label="Temperatura"><input name="temperature" type="number" min="0" max="2" step="0.1" defaultValue={Number(settings?.temperature ?? 0.3)} /></Field><Field label="Máximo de tokens"><input name="maxTokens" type="number" min="1" max="8000" defaultValue={Number(settings?.max_tokens ?? 500)} /></Field><Field label="Límite diario"><input name="daily" type="number" min="1" defaultValue={String(settings?.daily_message_limit ?? '')} /></Field><Field label="Límite mensual"><input name="monthly" type="number" min="1" defaultValue={String(settings?.monthly_message_limit ?? '')} /></Field><Field label="Instrucciones"><textarea name="systemPrompt" rows={7} defaultValue={String(settings?.system_prompt ?? '')} /></Field><Field label="Mensaje alternativo"><textarea name="fallback" rows={3} defaultValue={String(settings?.fallback_message ?? '')} /></Field></div></div><div className="form-actions">{(mutation.isError || test.isError) && <span className="form-error">{formatApiError(mutation.error ?? test.error)}</span>}{test.isSuccess && <span className="success-text"><CheckCircle2 size={16} />{test.data.response} · {test.data.durationMs} ms</span>}<Button type="button" variant="secondary" onClick={() => test.mutate()} disabled={!settings?.has_api_key || test.isPending}><FlaskConical size={16} />{test.isPending ? 'Probando…' : 'Probar proveedor'}</Button><Button type="submit" disabled={mutation.isPending}><Save size={16} />Guardar IA</Button></div></form></Card><Card className="knowledge-card"><div className="card-heading"><div><p className="eyebrow">Base de conocimiento</p><h2>Contenido autorizado</h2></div><Button variant="secondary" onClick={() => setAddingKnowledge(!addingKnowledge)}><Plus size={16} />Agregar</Button></div>{addingKnowledge && <form className="stacked-inline-form" onSubmit={(event) => { event.preventDefault(); const form = new FormData(event.currentTarget); addKnowledge.mutate({ title: form.get('title'), category: form.get('category') || null, content: form.get('content'), isActive: true }); }}><input name="title" required minLength={2} placeholder="Título" /><input name="category" placeholder="Categoría" /><textarea name="content" required rows={6} placeholder="Contenido verificado que puede utilizar el asistente" /><div className="button-row"><Button type="submit" disabled={addKnowledge.isPending}>Guardar contenido</Button><Button type="button" variant="ghost" onClick={() => setAddingKnowledge(false)}>Cancelar</Button></div></form>}{(addKnowledge.isError || deleteKnowledge.isError) && <p className="form-error">{formatApiError(addKnowledge.error ?? deleteKnowledge.error)}</p>}{query.data?.knowledge.length ? query.data.knowledge.map((item) => <article key={String(item.id)}><div className="article-heading"><Badge>{String(item.category ?? 'General')}</Badge><Button variant="ghost" aria-label={`Eliminar ${String(item.title)}`} onClick={() => { if (window.confirm('¿Eliminar este contenido de conocimiento?')) deleteKnowledge.mutate(String(item.id)); }}><Trash2 size={14} /></Button></div><h3>{String(item.title)}</h3><p>{String(item.content).slice(0, 160)}{String(item.content).length > 160 ? '…' : ''}</p></article>) : <EmptyState title="Sin conocimiento" detail="Agrega políticas, servicios y respuestas verificadas." />}</Card></div>;
}

function AiPanel({ companyId }: { companyId: string }) {
  const client = useQueryClient();
  const [addingKnowledge, setAddingKnowledge] = useState(false);
  const [testMessage, setTestMessage] = useState('Responde únicamente: conexión correcta');
  const [simulationMessage, setSimulationMessage] = useState('');
  const query = useQuery({ queryKey: ['ai', companyId], queryFn: () => api<{ settings: Record<string, unknown> | null; knowledge: Array<Record<string, unknown>> }>(`/admin/companies/${companyId}/ai`) });
  const usageQuery = useQuery({ queryKey: ['ai-analytics', companyId, 31], queryFn: () => api<{ summary: { today_messages: number; month_messages: number } }>(`/admin/companies/${companyId}/ai/analytics?days=31`) });
  const mutation = useMutation({ mutationFn: (body: unknown) => api(`/admin/companies/${companyId}/ai`, { method: 'PUT', ...jsonBody(body) }), onSuccess: () => client.invalidateQueries({ queryKey: ['ai', companyId] }) });
  const test = useMutation({
    mutationFn: (prompt: string) => api<{ response: string; usage: { totalTokens: number }; durationMs: number }>(`/admin/companies/${companyId}/ai/test`, { method: 'POST', ...jsonBody({ prompt }) }),
    onSuccess: async () => { await Promise.all([client.invalidateQueries({ queryKey: ['ai', companyId] }), client.invalidateQueries({ queryKey: ['ai-analytics', companyId] })]); },
  });
  const simulation = useMutation({
    mutationFn: (prompt: string) => api<{ response: string; usage: { totalTokens: number }; durationMs: number }>(`/admin/companies/${companyId}/ai/test`, { method: 'POST', ...jsonBody({ prompt }) }),
    onSuccess: () => client.invalidateQueries({ queryKey: ['ai-analytics', companyId] }),
  });
  const addKnowledge = useMutation({ mutationFn: (body: unknown) => api(`/admin/companies/${companyId}/ai/knowledge`, { method: 'POST', ...jsonBody(body) }), onSuccess: async () => { setAddingKnowledge(false); await client.invalidateQueries({ queryKey: ['ai', companyId] }); } });
  const deleteKnowledge = useMutation({ mutationFn: (id: string) => api(`/admin/companies/${companyId}/ai/knowledge/${id}`, { method: 'DELETE' }), onSuccess: () => client.invalidateQueries({ queryKey: ['ai', companyId] }) });

  if (query.isLoading) return <LoadingState />;
  const settings = query.data?.settings;
  const hasApiKey = Boolean(settings?.has_api_key);

  function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const form = new FormData(event.currentTarget);
    const daily = Number(form.get('daily') || 0);
    const monthly = Number(form.get('monthly') || 0);
    mutation.mutate({
      isEnabled: form.get('enabled') === 'on', provider: form.get('provider'), model: form.get('model'),
      apiKey: form.get('apiKey') || undefined, apiBaseUrl: form.get('apiBaseUrl') || null,
      responseMode: form.get('responseMode'), systemPrompt: form.get('systemPrompt') || null,
      fallbackMessage: form.get('fallback') || null, temperature: Number(form.get('temperature')),
      maxTokens: Number(form.get('maxTokens')), dailyMessageLimit: daily > 0 ? daily : null,
      monthlyMessageLimit: monthly > 0 ? monthly : null,
      pauseWhenAssigned: form.get('pauseWhenAssigned') === 'on',
      escalateOnHumanRequest: form.get('escalateOnHumanRequest') === 'on',
    });
  }

  return <>
    <div className="ai-settings-grid">
      <Card className="form-card ai-panel">
        <form onSubmit={submit}>
          <div className="form-section">
            <div><span className="section-icon"><Bot size={19} /></span><h2>Proveedor y comportamiento</h2><p>Cada empresa usa su propia API key y sus propias reglas de respuesta.</p></div>
            <div className="form-grid">
              <label className="toggle-field"><input name="enabled" type="checkbox" defaultChecked={Boolean(settings?.is_enabled)} /><span />Activar IA</label>
              <Field label="Proveedor"><select name="provider" defaultValue={String(settings?.provider ?? 'openai')}><option value="openai">OpenAI</option><option value="deepseek">DeepSeek</option><option value="gemini">Gemini</option></select></Field>
              <Field label="Modelo"><input name="model" defaultValue={String(settings?.model ?? 'gpt-4.1-mini')} required placeholder="gpt-4.1-mini, deepseek-chat, gemini-1.5-flash" /></Field>
              <Field label="API key" hint={hasApiKey ? 'Configurada. Déjala vacía para conservarla.' : 'Todavía no hay API key guardada.'}><input name="apiKey" type="password" autoComplete="new-password" placeholder="Pegar nueva API key" /></Field>
              <Field label="Modo de respuesta"><select name="responseMode" defaultValue={String(settings?.response_mode ?? 'outside_business_hours')}><option value="outside_business_hours">Responder fuera de horario laboral</option><option value="always">Responder 24/7</option><option value="unassigned_only">Responder solo sin agente asignado</option><option value="disabled">No responder automáticamente</option></select></Field>
              <Field label="Base URL opcional"><input name="apiBaseUrl" defaultValue={String(settings?.api_base_url ?? '')} placeholder="Usar endpoint oficial por defecto" /></Field>
              <Field label="Creatividad"><input name="temperature" type="number" min="0" max="1.5" step="0.05" defaultValue={Number(settings?.temperature ?? 0.3)} /></Field>
              <Field label="Máximo tokens"><input name="maxTokens" type="number" min="80" max="2000" step="20" defaultValue={Number(settings?.max_tokens ?? 500)} /></Field>
              <Field label="Límite diario"><input name="daily" type="number" min="0" defaultValue={String(settings?.daily_message_limit ?? '')} placeholder="Sin límite" /></Field>
              <Field label="Límite mensual"><input name="monthly" type="number" min="0" defaultValue={String(settings?.monthly_message_limit ?? '')} placeholder="Sin límite" /></Field>
              <label className="toggle-field"><input name="pauseWhenAssigned" type="checkbox" defaultChecked={settings?.pause_when_assigned !== false} /><span />Pausar si un agente toma la conversación</label>
              <label className="toggle-field"><input name="escalateOnHumanRequest" type="checkbox" defaultChecked={settings?.escalate_on_human_request !== false} /><span />Escalar cuando el cliente pide humano</label>
              <Field label="Prompt del administrador"><textarea name="systemPrompt" rows={7} defaultValue={String(settings?.system_prompt ?? '')} placeholder="Describe cómo debe responder la IA, tono, restricciones, servicios, reglas y cuándo debe pasar a un agente." /></Field>
              <Field label="Mensaje cuando no sabe responder"><textarea name="fallback" rows={3} defaultValue={String(settings?.fallback_message ?? '')} /></Field>
            </div>
          </div>
          <div className="ai-form-footer">
            <div className="ai-usage-strip"><span>Hoy: <strong>{usageQuery.data?.summary.today_messages ?? 0}</strong> respuestas</span><span>Mes: <strong>{usageQuery.data?.summary.month_messages ?? 0}</strong> respuestas</span></div>
            <div className="form-actions">{mutation.isError && <span className="form-error">{formatApiError(mutation.error)}</span>}{mutation.isSuccess && <span className="success-text"><CheckCircle2 size={16} />Guardado</span>}<Button type="submit" disabled={mutation.isPending}><Save size={16} />{mutation.isPending ? 'Guardando…' : 'Guardar IA'}</Button></div>
          </div>
        </form>
      </Card>
      <aside className="ai-side">
        <Card className="ai-side-card">
          <h3>Prueba de conexión</h3>
          <form onSubmit={(event) => { event.preventDefault(); test.mutate(testMessage); }}><input value={testMessage} onChange={(event) => setTestMessage(event.target.value)} required placeholder="Mensaje de prueba" /><Button type="submit" variant="secondary" disabled={!hasApiKey || test.isPending}><FlaskConical size={16} />{test.isPending ? 'Probando…' : 'Probar proveedor'}</Button></form>
          {test.isError && <div className="ai-result is-error"><strong>Prueba fallida</strong><span>{formatApiError(test.error)}</span></div>}
          {test.isSuccess && <div className="ai-result is-ok"><strong>Prueba correcta</strong><span>{test.data.response}</span><small>{test.data.usage.totalTokens} tokens · {test.data.durationMs} ms</small></div>}
        </Card>
        <Card className="ai-side-card">
          <h3>Simulador</h3>
          <form onSubmit={(event) => { event.preventDefault(); simulation.mutate(simulationMessage); }}><textarea rows={3} value={simulationMessage} onChange={(event) => setSimulationMessage(event.target.value)} required placeholder="Escribe un mensaje como si fuera un cliente" /><Button type="submit" variant="secondary" disabled={!hasApiKey || simulation.isPending}><Send size={16} />{simulation.isPending ? 'Simulando…' : 'Simular respuesta'}</Button></form>
          {simulation.isError && <div className="ai-result is-error"><strong>Simulación fallida</strong><span>{formatApiError(simulation.error)}</span></div>}
          {simulation.isSuccess && <div className="ai-result is-ok"><strong>Respuesta generada</strong><p>{simulation.data.response}</p><small>{simulation.data.usage.totalTokens} tokens · {simulation.data.durationMs} ms</small></div>}
        </Card>
      </aside>
    </div>
    <Card className="knowledge-card ai-knowledge-panel">
      <div className="card-heading"><div><p className="eyebrow">Base de conocimiento</p><h2>Conocimiento de la empresa</h2><p>Contenido corto y verificable que la IA puede usar al responder.</p></div><Button variant="secondary" onClick={() => setAddingKnowledge(!addingKnowledge)}><Plus size={16} />Agregar conocimiento</Button></div>
      {addingKnowledge && <form className="stacked-inline-form" onSubmit={(event) => { event.preventDefault(); const form = new FormData(event.currentTarget); addKnowledge.mutate({ title: form.get('title'), category: form.get('category') || null, content: form.get('content'), isActive: form.get('isActive') === 'on' }); }}><input name="title" required minLength={2} placeholder="Horarios, precios, garantías..." /><input name="category" placeholder="General" /><label className="toggle-field"><input name="isActive" type="checkbox" defaultChecked /><span />Activo</label><textarea name="content" required rows={4} placeholder="Escribe información concreta que la IA puede usar." /><div className="button-row"><Button type="submit" disabled={addKnowledge.isPending}>Agregar conocimiento</Button><Button type="button" variant="ghost" onClick={() => setAddingKnowledge(false)}>Cancelar</Button></div></form>}
      {(addKnowledge.isError || deleteKnowledge.isError) && <p className="form-error">{formatApiError(addKnowledge.error ?? deleteKnowledge.error)}</p>}
      {query.data?.knowledge.length ? query.data.knowledge.map((item) => <article key={String(item.id)}><div className="article-heading"><div className="inline-actions"><strong>{String(item.title)}</strong><Badge>{String(item.category ?? 'General')}</Badge><Badge tone={item.is_active ? 'green' : 'neutral'}>{item.is_active ? 'Activo' : 'Inactivo'}</Badge></div><Button variant="ghost" aria-label={`Eliminar ${String(item.title)}`} onClick={() => { if (window.confirm('¿Eliminar este contenido de conocimiento?')) deleteKnowledge.mutate(String(item.id)); }}><Trash2 size={14} />Eliminar</Button></div><p>{String(item.content)}</p></article>) : <EmptyState title="Sin conocimiento" detail="No hay conocimiento IA cargado todavía." />}
    </Card>
  </>;
}

type AiAnalytics = {
  days: number;
  summary: { total_requests: number; successful_requests: number; failed_requests: number; estimated_cost_usd: number; total_tokens: number; prompt_tokens: number; completion_tokens: number };
  byProvider: Array<{ provider: string; requests: number; successes: number; failures: number; tokens: number; estimated_cost_usd: number }>;
  byModel: Array<{ provider: string; model: string; requests: number; tokens: number; estimated_cost_usd: number }>;
  byDecision: Array<{ decision: string; count: number; successful: number; escalated: number }>;
  daily: Array<{ date: string; requests: number; tokens: number; estimated_cost_usd: number }>;
  recentConversations: Array<{ id: string; conversation_id: string; provider: string | null; model: string | null; decision: string; success: boolean; escalated_to_human: boolean; response_text: string | null; error_message: string | null; created_at: string }>;
};

function AiAnalyticsPanel({ companyId }: { companyId: string }) {
  const [days, setDays] = useState(30);
  const query = useQuery({ queryKey: ['ai-analytics', companyId, days], queryFn: () => api<AiAnalytics>(`/admin/companies/${companyId}/ai/analytics?days=${days}`) });
  if (query.isLoading) return <LoadingState label="Cargando análisis de IA…" />;
  if (query.isError) return <ErrorState message={formatApiError(query.error)} onRetry={() => void query.refetch()} />;
  const data = query.data!;
  const successRate = data.summary.total_requests ? data.summary.successful_requests * 100 / data.summary.total_requests : 0;
  return <>
    <div className="section-toolbar"><div><h2>Análisis IA</h2><p>Consumo, resultados y decisiones del asistente.</p></div><select className="compact-select" aria-label="Periodo" value={days} onChange={(event) => setDays(Number(event.target.value))}><option value="7">7 días</option><option value="30">30 días</option><option value="90">90 días</option><option value="180">180 días</option></select></div>
    <div className="stat-grid"><AiStat icon={Activity} label="Solicitudes" value={data.summary.total_requests} /><AiStat icon={CheckCircle2} label="Correctas" value={data.summary.successful_requests} /><AiStat icon={BarChart3} label="Tasa de éxito" value={`${successRate.toFixed(1)}%`} /><AiStat icon={Cpu} label="Tokens" value={data.summary.total_tokens} /></div>
    <div className="stat-grid stat-grid--three"><AiStat icon={CircleAlert} label="Fallidas" value={data.summary.failed_requests} /><AiStat icon={Cpu} label="Prompt tokens" value={data.summary.prompt_tokens} /><AiStat icon={Cpu} label="Respuesta tokens" value={data.summary.completion_tokens} /></div>
    <div className="report-table-grid">
      <AnalyticsTable title="Uso por proveedor" headers={['Proveedor', 'Solicitudes', 'Correctas']} rows={data.byProvider.map((item) => [item.provider, item.requests, item.successes])} />
      <AnalyticsTable title="Modelos" headers={['Modelo', 'Proveedor', 'Tokens']} rows={data.byModel.map((item) => [item.model, item.provider, item.tokens])} />
      <AnalyticsTable title="Decisiones" headers={['Decisión', 'Total', 'Escaladas']} rows={data.byDecision.map((item) => [item.decision, item.count, item.escalated])} />
    </div>
    <div className="dashboard-super-grid">
      <AnalyticsTable title="Uso diario" headers={['Día', 'Solicitudes', 'Tokens']} rows={data.daily.map((item) => [new Intl.DateTimeFormat('es-GT', { dateStyle: 'medium' }).format(new Date(`${item.date}T12:00:00`)), item.requests, item.tokens])} />
      <Card className="panel-card"><div className="card-heading"><div><p className="eyebrow">Conversaciones</p><h2>Actividad reciente</h2></div><Badge>{data.recentConversations.length}</Badge></div><div className="activity-list">{data.recentConversations.slice(0, 20).map((item) => <div className="activity-item" key={item.id}><span className={`activity-mark ${item.success ? '' : 'activity-mark--error'}`} /><div><strong>Conversación #{item.conversation_id} · {item.decision}</strong><span>{item.response_text || item.error_message || `${item.provider ?? 'Proveedor'} ${item.model ?? ''}`}</span></div><Badge tone={item.success ? 'green' : 'red'}>{item.success ? 'OK' : 'Error'}</Badge></div>)}{!data.recentConversations.length && <p className="muted">No hay respuestas o decisiones IA registradas.</p>}</div></Card>
    </div>
  </>;
}

function AiStat({ icon: Icon, label, value }: { icon: typeof Activity; label: string; value: string | number }) {
  return <Card className="stat-card"><span className="stat-card__icon"><Icon size={19} /></span><div><span>{label}</span><strong>{value}</strong></div></Card>;
}

function AnalyticsTable({ title, headers, rows }: { title: string; headers: string[]; rows: Array<Array<string | number>> }) {
  return <Card className="table-card"><div className="card-heading"><div><p className="eyebrow">Análisis IA</p><h2>{title}</h2></div></div>{rows.length ? <div className="data-table-wrap"><table className="data-table"><thead><tr>{headers.map((header) => <th key={header}>{header}</th>)}</tr></thead><tbody>{rows.map((row, index) => <tr key={`${title}-${index}`}>{row.map((cell, cellIndex) => <td key={cellIndex}>{cell}</td>)}</tr>)}</tbody></table></div> : <EmptyState title="Sin datos" detail="Todavía no hay uso registrado para este periodo." />}</Card>;
}

type CompanyOverview = {
  health: { company_enabled: boolean; has_active_integration: boolean; has_phone_number_id: boolean; has_verify_token: boolean; has_primary_admin: boolean; total_users: number; enabled_users: number; online_users: number; open_conversations: number; webhook_path: string | null; integration_updated_at: string | null; last_inbound_message_at: string | null; last_failure_at: string | null; last_failure_detail: string | null };
  summary: { users_count: number; contacts_count: number; open_conversations_count: number; messages_count: number; last_inbound_message_at: string | null };
  events: Array<{ id: string; event_type: string; source: string | null; success: boolean; template_name: string | null; language: string | null; to_phone_masked: string | null; phone_number_id: string | null; summary: string; created_at: string }>;
};

function CompanyOverviewPanel({ companyId }: { companyId: string }) {
  const query = useQuery({ queryKey: ['company-overview', companyId], queryFn: () => api<CompanyOverview>(`/admin/companies/${companyId}/overview`) });
  if (query.isLoading) return <LoadingState label="Cargando salud operativa…" />;
  if (query.isError || !query.data) return <ErrorState message={formatApiError(query.error)} />;
  const { health, summary, events } = query.data;
  const overall = !health.company_enabled ? 'Deshabilitada' : health.has_active_integration && health.has_primary_admin ? 'Operativa' : 'Requiere atención';
  const date = (value: string | null) => value ? new Intl.DateTimeFormat('es-CR', { dateStyle: 'short', timeStyle: 'short' }).format(new Date(value)) : '—';
  return <div className="company-overview-grid">
    <Card className="panel-card"><div className="card-heading"><div><p className="eyebrow">Módulos y salud</p><h2>Salud operativa</h2></div><Badge tone={overall === 'Operativa' ? 'green' : overall === 'Deshabilitada' ? 'neutral' : 'orange'}>{overall}</Badge></div><div className="health-kpis"><span>Empresa habilitada <strong>{health.company_enabled ? 'Sí' : 'No'}</strong></span><span>Integración activa <strong>{health.has_active_integration ? 'Sí' : 'No'}</strong></span><span>Phone Number ID <strong>{health.has_phone_number_id ? 'Sí' : 'No'}</strong></span><span>Verify token <strong>{health.has_verify_token ? 'Sí' : 'No'}</strong></span><span>Admin principal <strong>{health.has_primary_admin ? 'Sí' : 'No'}</strong></span><span>Usuarios activos <strong>{health.enabled_users} / {health.total_users}</strong></span><span>Usuarios online <strong>{health.online_users}</strong></span><span>Chats abiertos <strong>{health.open_conversations}</strong></span><span>Webhook <strong>{health.webhook_path ? 'OK' : 'N/D'}</strong></span></div><div className="health-meta"><p>Ruta webhook: {health.webhook_path ?? 'Sin ruta disponible'}</p><p>Integración actualizada: {date(health.integration_updated_at)}</p><p>Último inbound: {date(health.last_inbound_message_at)}</p><p>Último fallo: {date(health.last_failure_at)}</p>{health.last_failure_detail && <p className="form-error">{health.last_failure_detail}</p>}</div></Card>
    <Card className="panel-card"><div className="card-heading"><div><p className="eyebrow">Resumen</p><h2>Estado general</h2></div></div><div className="health-kpis"><span>Usuarios <strong>{summary.users_count}</strong></span><span>Contactos <strong>{summary.contacts_count}</strong></span><span>Chats abiertos <strong>{summary.open_conversations_count}</strong></span><span>Mensajes <strong>{summary.messages_count}</strong></span><span>Último inbound <strong>{date(summary.last_inbound_message_at)}</strong></span></div></Card>
    <div id="section-events" className="company-events"><Card className="table-card"><div className="card-heading"><div><p className="eyebrow">WhatsApp</p><h2>Eventos recientes de WhatsApp</h2></div><Badge>{events.length}</Badge></div>{events.length ? <div className="data-table-wrap"><table className="data-table"><thead><tr><th>Evento</th><th>Origen</th><th>Resumen</th><th>Estado</th><th>Fecha</th></tr></thead><tbody>{events.map((event) => <tr key={event.id}><td>{event.event_type}</td><td>{event.source ?? 'Sistema'}</td><td>{event.summary}</td><td><Badge tone={event.success ? 'green' : 'red'}>{event.success ? 'Correcto' : 'Error'}</Badge></td><td>{date(event.created_at)}</td></tr>)}</tbody></table></div> : <EmptyState title="Sin eventos" detail="Todavía no hay eventos de WhatsApp registrados para esta empresa." />}</Card></div>
  </div>;
}

function AuditPanel({ companyId }: { companyId: string }) {
  const query = useQuery({ queryKey: ['audits', companyId], queryFn: () => api<Array<Record<string, unknown>>>(`/admin/companies/${companyId}/audits`) });
  if (query.isLoading) return <LoadingState />;
  return <Card className="table-card"><div className="card-heading"><div><p className="eyebrow">Trazabilidad</p><h2>Auditoría administrativa</h2></div><Badge>{query.data?.length ?? 0} eventos</Badge></div>{query.data?.length ? <div className="data-table-wrap"><table className="data-table"><thead><tr><th>Acción</th><th>Actor</th><th>Detalle</th><th>Fecha</th></tr></thead><tbody>{query.data.map((item) => <tr key={String(item.id)}><td><Badge tone="orange">{String(item.action)}</Badge></td><td>{String(item.actor_name ?? item.actor_email ?? 'Sistema')}</td><td><code>{JSON.stringify(item.detail ?? {})}</code></td><td>{new Intl.DateTimeFormat('es-GT', { dateStyle: 'short', timeStyle: 'short' }).format(new Date(String(item.created_at)))}</td></tr>)}</tbody></table></div> : <EmptyState title="Sin actividad" detail="Los cambios administrativos aparecerán aquí sin incluir secretos." />}</Card>;
}
